SELECT sku, gtin, name, pack, case_units, flow, dc_slot, price_inr, cost_inr
FROM store.products
ORDER BY sku;

SELECT date, sku, units_sold FROM store.daily_sales
WHERE date IN (DATE '2026-06-12', DATE '2026-06-24', DATE '2026-06-25', DATE '2026-06-26')
ORDER BY date, sku;

SELECT date, sku, units_sold FROM store.daily_sales
WHERE sku IN ('ATTA-WW-1KG','ATTA-WW-10KG') AND date >= DATE '2026-06-01' AND date < DATE '2026-07-01'
ORDER BY date, sku;
